import hmac
import hashlib
import time
import struct
import os
from flask import Flask, request, jsonify, session, abort
from functools import wraps

app = Flask(__name__)
app.secret_key = os.urandom(32)

SECRET_KEY = os.urandom(32)
MAX_TOKEN_AGE = 3600  # 1 hour
MAX_CLOCK_SKEW = 300  # 5 minutes

def generate_token(user_id, role, issued_at=None):
    """Generate an authenticated token with timestamp."""
    if issued_at is None:
        issued_at = int(time.time())
    # Pack: user_id (4 bytes), role_len (1 byte), role (variable), timestamp (4 bytes)
    payload = struct.pack('>I', user_id) + struct.pack('>B', len(role)) + role.encode('utf-8') + struct.pack('>I', issued_at)
    mac = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()
    return (payload + mac).hex()

def parse_token(token_hex):
    """Parse and validate token. Returns (user_id, role, issued_at) or None."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token_bytes) < 4 + 1 + 1 + 4 + 32:
        return None

    # Extract fields
    user_id = struct.unpack('>I', token_bytes[0:4])[0]
    role_len = struct.unpack('>B', token_bytes[4:5])[0]

    if len(token_bytes) != 4 + 1 + role_len + 4 + 32:
        return None

    role = token_bytes[5:5+role_len].decode('utf-8')
    timestamp_offset = 5 + role_len
    issued_at = struct.unpack('>I', token_bytes[timestamp_offset:timestamp_offset+4])[0]

    # Verify MAC
    payload = token_bytes[:timestamp_offset+4]
    expected_mac = token_bytes[timestamp_offset+4:]

    if not hmac.compare_digest(hmac.new(SECRET_KEY, payload, hashlib.sha256).digest(), expected_mac):
        return None

    return (user_id, role, issued_at)

def check_token_freshness(issued_at):
    """Verify token is not expired. Returns True if token is fresh."""
    current_time = int(time.time())
    token_age = current_time - issued_at

    # Allow for clock skew: token could appear to be from slightly in the future
    if token_age < -MAX_CLOCK_SKEW:
        return False

    # Check if token has expired
    # A valid token has token_age in range [-MAX_CLOCK_SKEW, MAX_TOKEN_AGE]
    if token_age < MAX_TOKEN_AGE:
        return True

    return False

def require_role(required_role):
    """Decorator to enforce role-based access control."""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            token_hex = request.headers.get('X-Auth-Token')
            if not token_hex:
                abort(401)

            result = parse_token(token_hex)
            if result is None:
                abort(401)

            user_id, role, issued_at = result

            if not check_token_freshness(issued_at):
                abort(401)

            # Role hierarchy: admin > manager > user
            role_levels = {'user': 1, 'manager': 2, 'admin': 3}
            required_level = role_levels.get(required_role, 99)
            token_level = role_levels.get(role, 0)

            if token_level >= required_level:
                request.current_user_id = user_id
                request.current_role = role
                return f(*args, **kwargs)

            abort(403)
        return decorated_function
    return decorator

# Dummy hash used to keep login timing constant for unknown usernames,
# preventing username enumeration via timing side-channel.
_DUMMY_PASSWORD_HASH = hashlib.sha256(b'dummy_password_placeholder').hexdigest()

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and issue token."""
    data = request.get_json()
    if not data:
        abort(400)

    username = data.get('username', '')
    password = data.get('password', '')

    # Simulated user database (in production, use bcrypt/argon2)
    users = {
        'alice': {'id': 1, 'password_hash': hashlib.sha256(b'alice_pass').hexdigest(), 'role': 'admin'},
        'bob': {'id': 2, 'password_hash': hashlib.sha256(b'bob_pass').hexdigest(), 'role': 'user'},
        'carol': {'id': 3, 'password_hash': hashlib.sha256(b'carol_pass').hexdigest(), 'role': 'manager'},
    }

    user = users.get(username)
    # Always perform a constant-time comparison, even for unknown usernames,
    # to avoid leaking which usernames exist via response timing.
    stored_hash = user['password_hash'] if user else _DUMMY_PASSWORD_HASH
    password_matches = hmac.compare_digest(stored_hash, hashlib.sha256(password.encode()).hexdigest())

    if not user or not password_matches:
        abort(401)

    token = generate_token(user['id'], user['role'])
    return jsonify({'token': token, 'role': user['role']})

@app.route('/api/admin/users', methods=['GET'])
@require_role('admin')
def list_users():
    """Admin-only endpoint to list all users."""
    return jsonify({'users': [{'id': 1, 'name': 'alice'}, {'id': 2, 'name': 'bob'}, {'id': 3, 'name': 'carol'}]})

@app.route('/api/admin/transfer', methods=['POST'])
@require_role('admin')
def admin_transfer():
    """Admin-only endpoint to transfer funds."""
    data = request.get_json()
    return jsonify({'status': 'transferred', 'amount': data.get('amount')})

@app.route('/api/profile', methods=['GET'])
@require_role('user')
def get_profile():
    """Get current user profile."""
    return jsonify({'user_id': request.current_user_id, 'role': request.current_role})

if __name__ == '__main__':
    app.run(debug=False)
